# Windows WinRT OCR extraction script# Uses built-in Windows.Media.Ocr.OcrEngine - no external dependencies neededfunction Invoke-WinOcr {    param([string]$ImagePath)    # Load required WinRT assemblies    $null = [Windows.Storage.StorageFile,Windows.Storage,ContentType=WindowsRuntime]    $null = [Windows.Media.Ocr.OcrEngine,Windows.Foundation,ContentType=WindowsRuntime]    $null = [Windows.Graphics.Imaging.BitmapDecoder,Windows.Graphics,ContentType=WindowsRuntime]    # Helper to await WinRT async operations    function Await-Async($async) {        $task = [System.WindowsRuntimeSystemExtensions]::AsTask($async)        $task.Wait() | Out-Null        return $task.Result    }    # Get file and decode bitmap    $absPath = (Resolve-Path $ImagePath).Path    $storageFileTask = [Windows.Storage.StorageFile]::GetFileFromPathAsync($absPath)    $storageFile = Await-Async $storageFileTask    $streamTask = $storageFile.OpenAsync([Windows.Storage.FileAccessMode]::Read)    $stream = Await-Async $streamTask    $decoderTask = [Windows.Graphics.Imaging.BitmapDecoder]::CreateAsync($stream)    $decoder = Await-Async $decoderTask    $bitmapTask = $decoder.GetSoftwareBitmapAsync()    $bitmap = Await-Async $bitmapTask    # Run OCR    $engine = [Windows.Media.Ocr.OcrEngine]::TryCreateFromUserProfileLanguages()    if (-not $engine) {        $lang = [Windows.Globalization.Language]::new('en-US')        $engine = [Windows.Media.Ocr.OcrEngine]::TryCreateFromLanguage($lang)    }    $resultTask = $engine.RecognizeAsync($bitmap)    $result = Await-Async $resultTask    return $result.Text}Write-Host "=== EXTRACTING: membership_fees.jpg ===" -ForegroundColor Cyan$feesText = Invoke-WinOcr "C:\projects\banf\membership_fees.jpg"Write-Host $feesTextWrite-Host ""Write-Host "=== EXTRACTING: membership_events.jpg ===" -ForegroundColor Cyan$eventsText = Invoke-WinOcr "C:\projects\banf\membership_events.jpg"Write-Host $eventsText# Save to files for embedding$feesText | Out-File "C:\projects\banf\ocr_fees_raw.txt" -Encoding UTF8$eventsText | Out-File "C:\projects\banf\ocr_events_raw.txt" -Encoding UTF8Write-Host "`n=== Saved to ocr_fees_raw.txt and ocr_events_raw.txt ===" -ForegroundColor Green